# Queensland Flood Rainfall-Timing Ledger

During the 2010-2011 La Nina and Queensland floods, convert the CSX-272 package evidence into a numeric consistency ledger for the January 10, 2011 rainfall escalation. Treat gridded precipitation means and maxima as accumulated values over their declared package evidence window, not as January 10 daily totals.

Return only this JSON object, using two decimal places for millimeters and ratios:

```json
{
  "event_span_days": 0,
  "rain_anchor": {
    "date": "YYYY-MM-DD",
    "day_index": 0
  },
  "grid_evidence_window": "YYYY-MM-DD_to_YYYY-MM-DD",
  "grid_mm_ci": {
    "<gridded_source_key>": {
      "mean": 0.00,
      "max": 0.00,
      "ci": 0.00
    }
  },
  "ci_summary": {
    "mean": 0.00,
    "range": 0.00
  },
  "threshold_200mm": {
    "hits": 0,
    "max_margin_mm": 0.00
  },
  "point_peaks": {
    "<point_source_key>": {
      "date": "YYYY-MM-DD",
      "mm": 0.00,
      "lead_days": 0
    }
  },
  "grid_to_point_peak_ratio": 0.00,
  "answer": "<compact_result_code>"
}
```

Definitions: `ci = gridded maximum / gridded mean`; `day_index` is inclusive from the package start date; `lead_days` is the number of days from each point peak to 2011-01-10; `grid_to_point_peak_ratio` is the largest gridded accumulated-window maximum divided by the largest point daily peak. The 200 mm threshold comparison is a contextual accumulated-window magnitude check, not a claim that the gridded maximum occurred on January 10.

compute_gt_py:
#!/usr/bin/env python3
"""Compute deterministic numeric ground truth for CSX-272_Q2."""

from __future__ import annotations

import json
import re
from datetime import date, datetime
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-272"
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_002_Locked_event_anchor_2010-2011_La_Nina_and_Queensland_floods.json",
    "data/other/other_001_NASA_Earth_Observatory_heavy_rains_in_Queensland.html",
    "data/physical_hazard/physical_hazard_011_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_012_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_013_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_009_Open-Meteo_historical_daily_point_sample.json",
    "data/physical_hazard/physical_hazard_010_NASA_POWER_daily_point_sample.json",
]

RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Span and anchor-date arithmetic",
            "points": 4,
            "description": "Computes the inclusive 181-day event span and places 2011-01-10 at day index 132 from the event start.",
        },
        {
            "name": "Gridded precipitation ledger",
            "points": 5,
            "description": "Extracts all three gridded accumulated-window mean and maximum precipitation values, reports their evidence window, and derives each max/mean concentration index without treating them as January 10 daily totals.",
        },
        {
            "name": "Threshold calculation",
            "points": 4,
            "description": "Applies the 200 mm daily-rain reference, giving one gridded maximum at or above the threshold and a largest margin of 2.71 mm.",
        },
        {
            "name": "Point-series timing calculation",
            "points": 4,
            "description": "Finds both daily point-precipitation peaks, reports their dates and millimeters, and computes 16-day and 57-day leads to 2011-01-10.",
        },
        {
            "name": "Final numeric synthesis",
            "points": 3,
            "description": "Reports the 3.56 largest-gridded-maximum to largest-point-daily-peak ratio and uses the answer code grid_window_context_point_peaks_before_anchor.",
        },
    ],
}


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []

    def handle_data(self, data: str) -> None:
        self.parts.append(data)

    def text(self) -> str:
        return re.sub(r"\s+", " ", " ".join(self.parts)).strip()


def read_json(rel_path: str) -> dict[str, Any]:
    return json.loads((PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig"))


def read_text(rel_path: str) -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8-sig", errors="replace")


def parse_iso(value: str) -> date:
    return datetime.strptime(value, "%Y-%m-%d").date()


def parse_yyyymmdd(value: str) -> date:
    return datetime.strptime(value, "%Y%m%d").date()


def round2(value: float) -> float:
    return round(float(value), 2)


def inclusive_days(start: str, end: str) -> int:
    return (parse_iso(end) - parse_iso(start)).days + 1


def gridded_record(name: str, stats: dict[str, Any], mean_key: str, max_key: str) -> dict[str, float]:
    mean = float(stats[mean_key])
    max_value = float(stats[max_key])
    return {
        "mean": round2(mean),
        "max": round2(max_value),
        "ci": round2(max_value / mean),
    }


def grid_window(rel_path: str) -> str:
    data = read_json(rel_path)
    return f"{data.get('start')}_to_{data.get('end')}"


def open_meteo_peak(anchor_date: date) -> dict[str, Any]:
    data = read_json("data/physical_hazard/physical_hazard_009_Open-Meteo_historical_daily_point_sample.json")
    values = data["daily"]["precipitation_sum"]
    index = max(range(len(values)), key=lambda idx: values[idx])
    peak_date = parse_iso(data["daily"]["time"][index])
    return {
        "date": peak_date.isoformat(),
        "mm": round2(values[index]),
        "lead_days": (anchor_date - peak_date).days,
    }


def power_peak(anchor_date: date) -> dict[str, Any]:
    data = read_json("data/physical_hazard/physical_hazard_010_NASA_POWER_daily_point_sample.json")
    values = data["properties"]["parameter"]["PRECTOTCORR"]
    peak_key, peak_value = max(values.items(), key=lambda item: item[1])
    peak_date = parse_yyyymmdd(peak_key)
    return {
        "date": peak_date.isoformat(),
        "mm": round2(peak_value),
        "lead_days": (anchor_date - peak_date).days,
    }


def article_anchor_and_threshold() -> tuple[str, int]:
    html = read_text("data/other/other_001_NASA_Earth_Observatory_heavy_rains_in_Queensland.html")
    parser = TextExtractor()
    parser.feed(html)
    text = parser.text()
    date_match = re.search(r"January\s+10,\s+2011", text)
    threshold_match = re.search(r"greater than\s+(\d+)\s+millimeters", text)
    if not date_match or not threshold_match:
        raise ValueError("Could not parse article rain anchor and threshold")
    anchor_date = datetime.strptime(date_match.group(0), "%B %d, %Y").date().isoformat()
    return anchor_date, int(threshold_match.group(1))


def main() -> None:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_002_Locked_event_anchor_2010-2011_La_Nina_and_Queensland_floods.json"
    )
    era5_path = "data/physical_hazard/physical_hazard_011_ERA5-Land_hourly_aggregate_stats.json"
    gpm_path = "data/physical_hazard/physical_hazard_012_GPM_IMERG_V07_event_accumulated_precipitation.json"
    chirps_path = "data/physical_hazard/physical_hazard_013_CHIRPS_daily_event_accumulated_precipitation.json"
    era5_doc = read_json(era5_path)
    gpm_doc = read_json(gpm_path)
    chirps_doc = read_json(chirps_path)
    era5 = era5_doc["stats"]
    gpm = gpm_doc["stats"]
    chirps = chirps_doc["stats"]

    start_date = anchor["temporal_window"]["start_date"]
    end_date = anchor["temporal_window"]["end_date"]
    rain_anchor_date, threshold_mm = article_anchor_and_threshold()
    rain_anchor = parse_iso(rain_anchor_date)

    grid = {
        "era5_land": gridded_record("era5_land", era5, "precipitation_sum_mm_mean", "precipitation_sum_mm_max"),
        "gpm_imerg": gridded_record("gpm_imerg", gpm, "gpm_event_precip_mm_mean", "gpm_event_precip_mm_max"),
        "chirps": gridded_record("chirps", chirps, "chirps_event_precip_mm_mean", "chirps_event_precip_mm_max"),
    }
    ci_values = [item["ci"] for item in grid.values()]
    grid_max_values = [item["max"] for item in grid.values()]
    point_peaks = {
        "open_meteo": open_meteo_peak(rain_anchor),
        "nasa_power": power_peak(rain_anchor),
    }
    point_peak_values = [item["mm"] for item in point_peaks.values()]
    threshold_margins = [value - threshold_mm for value in grid_max_values]

    primary_gt = {
        "event_span_days": inclusive_days(start_date, end_date),
        "rain_anchor": {
            "date": rain_anchor_date,
            "day_index": (rain_anchor - parse_iso(start_date)).days + 1,
        },
        "grid_evidence_window": grid_window(era5_path),
        "grid_mm_ci": grid,
        "ci_summary": {
            "mean": round2(sum(ci_values) / len(ci_values)),
            "range": round2(max(ci_values) - min(ci_values)),
        },
        "threshold_200mm": {
            "hits": sum(1 for value in grid_max_values if value >= threshold_mm),
            "max_margin_mm": round2(max(threshold_margins)),
        },
        "point_peaks": point_peaks,
        "grid_to_point_peak_ratio": round2(max(grid_max_values) / max(point_peak_values)),
        "answer": "grid_window_context_point_peaks_before_anchor",
    }

    computed_gt = {
        "schema_version": "1.0",
        "task_id": "CSX-272_Q2",
        "event_id": "CSX-272",
        "target_family": "precipitation_timing_consistency_ledger",
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L4",
        "primary_gt": primary_gt,
        "rubric": RUBRIC,
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_span": {
                "start_date": start_date,
                "end_date": end_date,
            },
        },
        "key_values": {
            "threshold_mm": threshold_mm,
            "source_grid_count": len(grid),
            "grid_windows": {
                "era5_land": grid_window(era5_path),
                "gpm_imerg": grid_window(gpm_path),
                "chirps": grid_window(chirps_path),
            },
            "source_point_series_count": len(point_peaks),
            "largest_grid_max_mm": max(grid_max_values),
            "largest_point_peak_mm": max(point_peak_values),
            "point_peak_lead_day_range": [
                min(item["lead_days"] for item in point_peaks.values()),
                max(item["lead_days"] for item in point_peaks.values()),
            ],
        },
        "tolerances": {
            "mm": 0.02,
            "ratio": 0.01,
            "days": 0,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }

    OUTPUT_PATH.write_text(json.dumps(computed_gt, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
